import{_ as o,r as n,o as p,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"form() - October CMS - 3.x","titleTemplate":false,"description":"Twig Function","frontmatter":{"subtitle":"Twig Function"},"headers":[{"level":2,"title":"form_open()","slug":"form-open","link":"#form-open","children":[]},{"level":2,"title":"form_ajax()","slug":"form-ajax","link":"#form-ajax","children":[]},{"level":2,"title":"form_close()","slug":"form-close","link":"#form-close","children":[]},{"level":2,"title":"Passing Attributes to the Generated Element","slug":"passing-attributes-to-the-generated-element","link":"#passing-attributes-to-the-generated-element","children":[]}],"relativePath":"3.x/markup/function/form.md","filePath":"3.x/markup/function/form.md"}'),u={name:"3.x/markup/function/form.md"};function r(d,a,g,k,m,h){const t=n("pre-heading"),e=n("post-heading");return p(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"form()",-1)),s(e),a[1]||(a[1]=i(`<p>Functions prefixed with <code>form_</code> perform tasks that are useful when dealing with forms. The helper maps directly to the <code>Form</code> PHP class and its methods. For example:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> form_close<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>The above is the PHP equivalent of the following:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><blockquote><p><strong>Note</strong>: Methods in <em>camelCase</em> should be converted to <em>snake_case</em>.</p></blockquote><h2 id="form-open"><a href="#form-open" class="header-anchor">#</a> form_open()</h2><p>Outputs a standard <code>&lt;form&gt;</code> opening tag along with the <code>_session_key</code> and <code>_token</code> hidden fields for CSRF protection. If you are using the <a href="./../../cms/ajax/introduction.html">AJAX Framework</a>, it is recommended that you use <code>form_ajax()</code> instead.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> form_open<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>Attributes can be passed in the first argument.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> form_open<span class="token punctuation">(</span><span class="token punctuation">{</span> class<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>form-horizontal<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>The above example would output as the following:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-horizontal<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>There are some special options that can also be used alongside the attributes.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> form_open<span class="token punctuation">(</span><span class="token punctuation">{</span> request<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>onUpdate<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>The function support the following options:</p><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>method</strong></td><td>Request method. Corresponds to the <strong>method</strong> FORM tag attribute. Eg: POST, GET, PUT, DELETE</td></tr><tr><td><strong>request</strong></td><td>A handler name to execute on the server when the form is posted. See the <a href="./../../cms/ajax/handlers.html">AJAX handlers</a> article for details about event handlers.</td></tr><tr><td><strong>url</strong></td><td>Specifies URL to post the form to. Corresponds to the <strong>action</strong> FORM tag attribute.</td></tr><tr><td><strong>files</strong></td><td>Determines whether the form will submit files. Accepted values: <strong>true</strong> and <strong>false</strong>.</td></tr><tr><td><strong>model</strong></td><td>A model object for the form model binding.</td></tr></tbody></table></div><h2 id="form-ajax"><a href="#form-ajax" class="header-anchor">#</a> form_ajax()</h2><p>Outputs an AJAX enabled FORM opening tag. The first parameter of the <code>form_ajax()</code> function is the AJAX handler name. The handler can be defined in the layout or page PHP section code, it can also be defined in a component. You may find more information about AJAX in the <a href="./../ajax/introduction.html">AJAX Framework</a> article.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> form_ajax<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onUpdate<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>Attributes can be passed in the second argument.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> form_ajax<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onSave<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token punctuation">{</span> class<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>form-horizontal<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>The above example would output as the following:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSave<span class="token punctuation">&quot;</span></span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>form-horizontal<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>There are some special options that can also be used alongside the attributes.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> form_ajax<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onDelete<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token punctuation">{</span> data<span class="token punctuation">:</span> <span class="token punctuation">{</span> id<span class="token punctuation">:</span> <span class="token number">2</span> <span class="token punctuation">}</span><span class="token punctuation">,</span> confirm<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>Really delete this record?<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> form_ajax<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onRefresh<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token punctuation">{</span> update<span class="token punctuation">:</span> <span class="token punctuation">{</span> statistics<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>#statsPanel<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><blockquote><p><strong>Note</strong>: When attempting to reference a component&#39;s alias with <code>__SELF__</code> as an argument to <code>form_ajax()</code> you must first build the string you wish to use outside of the call itself. Example:</p></blockquote><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> targetPartial <span class="token operator">=</span> <span class="token string"><span class="token punctuation">&quot;</span><span class="token punctuation">&#39;</span><span class="token punctuation">&quot;</span></span> <span class="token operator">~</span> __SELF__ <span class="token operator">~</span> <span class="token string"><span class="token punctuation">&quot;</span>::statistics&#39;: &#39;#statsPanel&#39;<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> form_ajax<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>onUpdate<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token punctuation">{</span> update<span class="token punctuation">:</span> targetPartial <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>The function support the following options:</p><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>success</strong></td><td>JavaScript string to execute on successful result.</td></tr><tr><td><strong>error</strong></td><td>JavaScript string to execute on failed result.</td></tr><tr><td><strong>confirm</strong></td><td>A confirmation message to display before sending the request.</td></tr><tr><td><strong>redirect</strong></td><td>On successful result, redirect to a URL.</td></tr><tr><td><strong>update</strong></td><td>An array of partials to update on success in the following format: { &#39;partial&#39;: &#39;#element&#39; }.</td></tr><tr><td><strong>data</strong></td><td>Extra data to include with the request in the following format: { &#39;myvar&#39;: &#39;myvalue&#39; }.</td></tr></tbody></table></div><h2 id="form-close"><a href="#form-close" class="header-anchor">#</a> form_close()</h2><p>Outputs a standard FORM closing tag. This tag is generally available to provide consistency in usage.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> form_close<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>The above example would output as the following:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="passing-attributes-to-the-generated-element"><a href="#passing-attributes-to-the-generated-element" class="header-anchor">#</a> Passing Attributes to the Generated Element</h2><p>You can pass additional attributes to the <code>Form::open()</code> method by passing an array of attribute names and values to be rendered on the final generated <code>&lt;form&gt;</code> element.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token keyword">array</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;id&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;example&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;class&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;something&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    // ..
<span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>The above example would output the following:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">method</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>POST<span class="token punctuation">&quot;</span></span> <span class="token attr-name">action</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">accept-charset</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>UTF-8<span class="token punctuation">&quot;</span></span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>example<span class="token punctuation">&quot;</span></span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>something<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div>`,39))])}const v=o(u,[["render",r]]);export{w as __pageData,v as default};
